def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            nines = 0
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                if grid[y][x] == 9:
                    nines += 1
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            not seen[ny][nx] and grid[ny][nx] != 0):
                        seen[ny][nx] = True
                        stack.append((ny, nx))
            components.append((nines, cells))

    out = [row[:] for row in grid]
    if components:
        _, cells = min(components, key=lambda item: item[0])
        for r, c in cells:
            out[r][c] = 0
    return out
